contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public function with parameters driving the contract
    function run(address to, uint256 amt) public payable {
        // no precondition on params
        // ensure we observe whether transfer reverts
        bool reverted;
        c.transfer(to, amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // General rule: transfers to the zero address must always revert; transfers to non-zero may succeed or revert for other reasons
        assert((to == address(0) && reverted) || (to != address(0)));
    }
    receive() external payable { }
}

